const main = document.querySelector('main');
function computedBox(el, label) {
  if (!el) return {label, found: false};
  const cs = getComputedStyle(el);
  const rect = el.getBoundingClientRect();
  return {label, found: true, tag: el.tagName, cls: el.className?.toString().slice(0,80), width: rect.width, x: rect.x, right: window.innerWidth - rect.right, paddingRight: cs.paddingRight, gap: cs.gap, columnGap: cs.columnGap, display: cs.display};
}
// find the gallery image and the content column (price/size block) to inspect their common ancestor row
const priceEl = [...document.querySelectorAll('*')].find(e => e.textContent?.trim() === 'A$895.00' && e.children.length === 0);
const galleryImg = document.querySelector('main img, main [role="img"]');
const results = [];
results.push(computedBox(document.getElementById('app-main'), '#app-main'));
results.push(computedBox(main, 'main'));
if (priceEl) {
  let row = priceEl;
  for (let i=0;i<8 && row; i++) { row = row.parentElement; }
  results.push(computedBox(row, 'ancestor(8up from price)'));
}
if (galleryImg) {
  let gcol = galleryImg;
  for (let i=0;i<6 && gcol; i++) { gcol = gcol.parentElement; }
  results.push(computedBox(gcol, 'gallery ancestor(6up)'));
}
JSON.stringify(results, null, 2);

function cb(el){ if(!el) return null; const cs=getComputedStyle(el); const r=el.getBoundingClientRect();
  return {tag:el.tagName, cls:String(el.className).slice(0,60), w:Math.round(r.width), x:Math.round(r.x), right:Math.round(window.innerWidth-r.right), pr:cs.paddingRight, pb:cs.paddingBottom, gap:cs.columnGap, display:cs.display, flex:cs.flex}; }

const priceEl = [...document.querySelectorAll('*')].find(e => e.textContent?.trim() === 'A$895.00' && e.children.length === 0);
let contentCol = priceEl.parentElement;
// walk up until this element's parent has 2+ element children (the flex row: gallery col + content col)
let row = contentCol;
const chain = [];
for (let i=0;i<10 && row; i++) {
  chain.push(cb(row));
  row = row.parentElement;
}
JSON.stringify(chain, null, 2);

const res = await fetch('/mobify/proxy/api/product/shopper-search/v1/organizations/f_ecom_bkzk_002/product-search?q=a&limit=24&siteId=ZimmermannAU&locale=en&currency=AUD');
const data = await res.json();
JSON.stringify((data.hits||[]).map(h => ({id: h.productId || h.productName, name: h.productName, image: h.image?.link})).slice(0,24));

