import React, { useState } from 'react';
import { AspectRatio, Image, chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import DynamicImage from '@salesforce/retail-react-app/app/components/dynamic-image';
import { ZimmButton } from '../zimmButton';
import { GALLERY_ITEM_ASPECT_RATIO } from './zimmMediaTile.css';
import { buildDisImageSrc } from 'app/utils/buildDisImageSrc';

/** Same shape base SFCC's `DynamicImage`/`getResponsivePictureAttributes` accept. */
export type ZimmMediaTileWidths = (number | string)[] | Record<string, number | string>;

const messages = defineMessages({
  play: { id: 'product_gallery.video.play', defaultMessage: 'Play video' },
  pause: { id: 'product_gallery.video.pause', defaultMessage: 'Pause video' },
  mute: { id: 'product_gallery.video.mute', defaultMessage: 'Mute video' },
  unmute: { id: 'product_gallery.video.unmute', defaultMessage: 'Unmute video' },
});

const ZIMM_MEDIA_TILE_RECIPE = 'ZimmMediaTile';

export type ZimmGalleryPhotoItem = {
  kind: 'photo';
  src: string;
  alt: string;
};

export type ZimmGalleryVideoItem = {
  kind: 'video';
  /**
   * Poster frame shown in place of real playback. No product video data source exists yet —
   * SFCC-188 ("PDP – Product Video in Gallery") is blocked on a content-modelling workshop for
   * how video is stored on the product and ordered in the gallery. This renders the positional
   * slot and a real, keyboard-operable control shell (play/pause, mute) ready for SFCC-188 to
   * wire an actual source into, but the controls only toggle local UI state today.
   */
  posterSrc: string;
  posterAlt: string;
};

export type ZimmGalleryMediaItem = ZimmGalleryPhotoItem | ZimmGalleryVideoItem;

export type ZimmMediaTileProps = {
  item: ZimmGalleryMediaItem;
  /** Skips `loading="lazy"` — pass for the item that should load with LCP priority. */
  eager?: boolean;
  /**
   * SFCC-731 AC 19 — this tile's own real rendered width per breakpoint (px/vw, or a single
   * value), e.g. `{base: '100vw', lg: 902}`. The atom has no layout context of its own — it's
   * reused inside full-bleed stacked items, 2/4-up grid cells, and a fluid mobile carousel, each
   * a different real width — so each caller supplies its own. When omitted, the image renders
   * at its raw source resolution with no responsive `srcset` (this atom's previous behaviour).
   */
  widths?: ZimmMediaTileWidths;
  /** DIS `q` param (0-100), forwarded to `buildDisImageSrc`. Only used when `widths` is given. */
  quality?: number;
};

/**
 * Atom — a single photo or video gallery tile's own visual content: aspect-ratio box, the image
 * itself (with a load-failure fallback), and — for a video item — its play/pause/mute control
 * shell. No interactive "open gallery" trigger behaviour lives here; that's the caller's
 * concern (see ZimmProductGallery's sibling `triggerOverlay` button and ZimmGalleryOverlay's
 * plain scrollable stack).
 *
 * Reused across the PDP's default gallery state (ZimmProductGallery) and its expanded/overlay
 * state (ZimmGalleryOverlay, SFCC-731 AC 12-25) so the load-failure and aspect-ratio handling
 * can't drift between the two.
 */
export const ZimmMediaTile = ({ item, eager = false, widths, quality }: ZimmMediaTileProps) => {
  const intl = useIntl();
  const styles = useMultiStyleConfig(ZIMM_MEDIA_TILE_RECIPE, {});
  // No real playback source yet (see ZimmGalleryVideoItem) — these toggle local UI state only,
  // ready for SFCC-188 to wire a real <video>/Vimeo source behind.
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(true);
  // SFCC-731 AC 21 — a failed load keeps the aspect-ratio box (no layout shift) with a neutral
  // fill instead of the browser's broken-image icon. Tracks the SOURCE that failed, not a plain
  // boolean — a tile is reused at the same list position across renders (index-keyed), so a
  // plain boolean would keep showing the fallback for a brand-new, valid source after a
  // variation swap replaces a previously-failed one (CodeRabbit, PR #81).
  const [erroredSrc, setErroredSrc] = useState<string | null>(null);
  const src = item.kind === 'photo' ? item.src : item.posterSrc;
  const alt = item.kind === 'photo' ? item.alt : item.posterAlt;
  const hasError = erroredSrc === src;

  // SFCC-731 AC 19 — responsive DIS srcset when the caller knows its own real rendered width
  // (`widths`); otherwise the raw source, unchanged from this atom's previous behaviour. Shared
  // between the photo and video-poster branches below so they can't drift from each other.
  const image = hasError ? (
    <chakra.div __css={styles.mediaFallback} role="img" aria-label={alt} aria-hidden={alt === '' || undefined} />
  ) : widths ? (
    <DynamicImage
      as={Image}
      src={buildDisImageSrc(src, quality)}
      widths={widths}
      imageProps={{
        alt,
        loading: eager ? 'eager' : 'lazy',
        width: '100%',
        height: '100%',
        objectFit: 'cover',
        onError: () => setErroredSrc(src),
      }}
      // AspectRatio's own CSS (`& > *:not(style)`) sizes DynamicImage's outer Box correctly,
      // since that Box is AspectRatio's direct child — but `<picture>` (DynamicImage's own
      // markup, one level further in, not exposed as a prop) is `display: inline` by default
      // and gets no sizing from anywhere, so the actual image was rendering near its intrinsic
      // pixel size instead of filling the tile. `imageProps`'s width/height only reaches the
      // innermost <img>, which then has nothing correctly-sized to resolve "100%" against.
      __css={{ '& picture': { display: 'block', width: '100%', height: '100%' } }}
    />
  ) : (
    <Image
      src={src}
      alt={alt}
      loading={eager ? 'eager' : 'lazy'}
      objectFit="cover"
      onError={() => setErroredSrc(src)}
    />
  );

  if (item.kind === 'photo') {
    return <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO}>{image}</AspectRatio>;
  }

  return (
    <>
      <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO}>{image}</AspectRatio>
      <chakra.div __css={styles.videoControlsWrapper}>
        <ZimmButton
          variant="icon"
          icon={playing ? 'pause' : 'play'}
          label={intl.formatMessage(playing ? messages.pause : messages.play)}
          onClick={() => setPlaying((p) => !p)}
        />
        <ZimmButton
          variant="icon"
          icon="mute"
          label={intl.formatMessage(muted ? messages.unmute : messages.mute)}
          onClick={() => setMuted((m) => !m)}
        />
      </chakra.div>
    </>
  );
};

export default ZimmMediaTile;

